import{_ as s,o as t,c as a,a3 as d}from"./chunks/framework.B9M8MqoS.js";const v=JSON.parse('{"title":"Racks and devices","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/racks.md","filePath":"developers/commands/racks.md"}'),o={name:"developers/commands/racks.md"};function c(n,e,r,i,p,l){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="racks-and-devices" tabindex="-1">Racks and devices <a class="header-anchor" href="#racks-and-devices" aria-label="Permalink to &quot;Racks and devices&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; rack list</span></span>
<span class="line"><span>s32&gt; rack rename 0 Lead</span></span>
<span class="line"><span>s32&gt; device add 0 step-seq</span></span>
<span class="line"><span>s32&gt; device list 0</span></span>
<span class="line"><span>s32&gt; stepseq set 0 1 step 0 active=1 note=60 vel=100</span></span>
<span class="line"><span>s32&gt; stepseq get 0 1</span></span>
<span class="line"><span>s32&gt; rack duplicate 0 1</span></span>
<span class="line"><span>s32&gt; rack bypass 1 on</span></span></code></pre></div><p><code>RACK</code> and <code>DEV</code> are positions: rack <code>0</code> is the first <a href="/versions/v1.0.1/racks/">rack</a>, device <code>0</code> the first device in it. Ids (<code>rack list</code>, <code>device list</code>) are used only by <code>lfo assign</code> and <code>macro set … mode=device</code>.</p><h2 id="racks" tabindex="-1">Racks <a class="header-anchor" href="#racks" aria-label="Permalink to &quot;Racks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>rack list</code></td><td>Position, id, bypass, device count and name of each rack. An empty slot&#39;s id prints <code>-</code></td></tr><tr><td><code>rack rename RACK NAME</code></td><td>Keeps the first 10 characters</td></tr><tr><td><code>rack bypass RACK on|off</code></td><td></td></tr><tr><td><code>rack clear RACK</code></td><td>Asks first. Removes every device</td></tr><tr><td><code>rack duplicate SRC DST</code></td><td></td></tr></tbody></table><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>device list RACK</code></td><td>Position, type, id and name of each device</td></tr><tr><td><code>device add RACK TYPE</code></td><td>Adds a <a href="/versions/v1.0.1/devices/">device</a> to the rack. <code>TYPE</code> is a name (<code>midi-in</code>, <code>midi-out</code>, <code>clock</code>, <code>arp</code>, <code>step-seq</code>, …) or its number from <code>schema</code></td></tr><tr><td><code>device remove RACK DEV</code></td><td></td></tr><tr><td><code>device move RACK FROM TO</code></td><td>Reorders inside the rack. MIDI IN stays first, MIDI OUT last</td></tr><tr><td><code>device param get RACK DEV PARAM</code></td><td>Value and range</td></tr><tr><td><code>device param set RACK DEV PARAM VALUE</code></td><td>Rounded to a whole number and clamped to the range</td></tr><tr><td><code>device host-device RACK DEV</code></td><td>Which USB Host device a MIDI IN or MIDI OUT uses: <code>ALL</code> or a device name</td></tr><tr><td><code>device host-device RACK DEV all|N|NAME</code></td><td>Picks ALL, or a device from <code>host-device list</code> by number or name</td></tr></tbody></table><p>An empty rack takes <strong>MIDI IN</strong> or <strong>CLOCK</strong> first. A device that can&#39;t go there, or a full rack, answers <code>BadRequest</code>. <code>NoSpace</code> means the S32 has no room for another device.</p><p><code>PARAM</code> is a parameter name (<code>bypass</code>, <code>mode</code>, <code>rate</code>, <code>gate</code>, <code>clock-division</code>, <code>port</code>, <code>host-device</code>, …) or its number from <code>schema</code>, not the row on the screen.</p><h2 id="usb-host-devices" tabindex="-1">USB Host devices <a class="header-anchor" href="#usb-host-devices" aria-label="Permalink to &quot;USB Host devices&quot;">​</a></h2><p><code>host-device list</code> prints the devices this project knows on the <a href="/versions/v1.0.1/concepts/routing#usb-host">USB HOST port</a>, numbered as <strong>HOST DEVICE</strong> counts them (<code>0</code> is <strong>ALL</strong>). A device you unplugged stays listed, marked <code>(unplugged)</code>. <code>stored</code> is the name exactly as the project keeps it, in the case the device reported; it is left out when the device has no name. <code>device host-device</code> matches the panel text, not <code>stored</code>, so pick a second identical device by its number.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; host-device list</span></span>
<span class="line"><span>host devices: 4 of 8</span></span>
<span class="line"><span>  0 ALL</span></span>
<span class="line"><span>  1 KEYBOARD  (1209:0001 at 011)  stored &quot;Keyboard&quot;</span></span>
<span class="line"><span>  2 KEYBOARD (2) (unplugged)  (1209:0001 at 012)  stored &quot;Keyboard&quot;</span></span>
<span class="line"><span>  3 SYNTH (unplugged)  (1209:0002 at 021)  stored &quot;Synth&quot;</span></span>
<span class="line"><span>  4 1209:0003  (1209:0003 at 031)</span></span>
<span class="line"><span>s32&gt; device host-device 0 0 keyboard</span></span>
<span class="line"><span>rack 0 device 0 HOST DEVICE = KEYBOARD</span></span></code></pre></div><p><strong>HOST DEVICE</strong> only does something while that MIDI IN or MIDI OUT has <strong>PORT</strong> set to <strong>USB HOST</strong>.</p><p>IN SNAPSHOT and ALLOW MORPH for device parameters are under <a href="./snapshots#in-snapshot"><code>snapshot flags</code></a>.</p><h2 id="step-seq" tabindex="-1">Step Seq <a class="header-anchor" href="#step-seq" aria-label="Permalink to &quot;Step Seq&quot;">​</a></h2><p><code>stepseq get RACK DEV</code> prints all 16 steps. <code>DEV</code> must be a Step Seq.</p><p><code>stepseq set RACK DEV step N key=value …</code> changes one step (<code>0</code>–<code>15</code>). Keys: <code>active</code>, <code>note</code>, <code>vel</code>, <code>gate</code>, <code>ch</code>, <code>prob</code>.</p>`,17)])])}const m=s(o,[["render",c]]);export{v as __pageData,m as default};
